export const layerQuestionBank: AssessmentQuestion[] = Object.keys(layerDrafts).map(Number).map((layer) => layer as AcademyLayer).flatMap((layer) => {
  const categories = layerDrafts[layer];
  return (Object.keys(categories) as AssessmentCategory[]).flatMap((category) =>
    categories[category].map((draft, index) => question(layer, category, index + 1, draft)),
  );
});

